-- Fresh PostgreSQL/Supabase installation. Do not apply over existing tables.
CREATE TABLE "Plan" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"intervalMinutes" INTEGER NOT NULL,"maxMonitors" INTEGER NOT NULL,"maxSourcesPerMonitor" INTEGER NOT NULL DEFAULT 3,"cooldownMinutes" INTEGER NOT NULL DEFAULT 720);
CREATE TABLE "UserPlan" ("userId" UUID PRIMARY KEY,"planId" TEXT NOT NULL DEFAULT 'free',"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "UserPlan_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Monitor" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"name" TEXT NOT NULL,"keywords" TEXT[] NOT NULL,"excludeKeywords" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"matchMode" TEXT NOT NULL DEFAULT 'ANY',"status" TEXT NOT NULL DEFAULT 'ACTIVE',"nextCheckAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastCheckedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Monitor_status_nextCheckAt_idx" ON "Monitor"("status","nextCheckAt");CREATE INDEX "Monitor_userId_idx" ON "Monitor"("userId");
CREATE TABLE "Source" ("id" UUID PRIMARY KEY,"monitorId" UUID NOT NULL,"url" TEXT NOT NULL,"lastHash" TEXT,"lastText" TEXT,"lastError" TEXT,"checkedAt" TIMESTAMP(3),CONSTRAINT "Source_monitorId_fkey" FOREIGN KEY ("monitorId") REFERENCES "Monitor"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Source_monitorId_url_key" ON "Source"("monitorId","url");
CREATE TABLE "Detection" ("id" UUID PRIMARY KEY,"monitorId" UUID NOT NULL,"sourceId" UUID NOT NULL,"fingerprint" TEXT NOT NULL,"title" TEXT NOT NULL,"snippet" TEXT NOT NULL,"url" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"publishedAt" TIMESTAMP(3),"sourceUpdatedAt" TIMESTAMP(3),"dateConfidence" TEXT NOT NULL DEFAULT 'UNKNOWN',"eventType" TEXT NOT NULL DEFAULT 'NEW',CONSTRAINT "Detection_monitorId_fkey" FOREIGN KEY ("monitorId") REFERENCES "Monitor"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Detection_monitorId_fingerprint_key" ON "Detection"("monitorId","fingerprint");CREATE INDEX "Detection_monitorId_createdAt_idx" ON "Detection"("monitorId","createdAt");
CREATE TABLE "Notification" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"detectionId" UUID NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_detectionId_fkey" FOREIGN KEY ("detectionId") REFERENCES "Detection"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Notification_userId_detectionId_key" ON "Notification"("userId","detectionId");CREATE INDEX "Notification_userId_createdAt_idx" ON "Notification"("userId","createdAt");
CREATE TABLE "Device" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"expoToken" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "Device_userId_idx" ON "Device"("userId");
CREATE TABLE "Feedback" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"notificationId" UUID NOT NULL,"useful" BOOLEAN NOT NULL,"savedMoney" DOUBLE PRECISION,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE UNIQUE INDEX "Feedback_userId_notificationId_key" ON "Feedback"("userId","notificationId");
CREATE TABLE "CatalogSource" ("id" UUID PRIMARY KEY,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"url" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "CatalogSource_category_active_idx" ON "CatalogSource"("category","active");
CREATE TABLE "DiscoveryQuery" ("id" UUID PRIMARY KEY,"monitorId" UUID NOT NULL UNIQUE,"query" TEXT NOT NULL,"lastRunAt" TIMESTAMP(3),"lastError" TEXT,CONSTRAINT "DiscoveryQuery_monitorId_fkey" FOREIGN KEY ("monitorId") REFERENCES "Monitor"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DiscoveredResult" ("id" UUID PRIMARY KEY,"monitorId" UUID NOT NULL,"urlHash" TEXT NOT NULL,"url" TEXT NOT NULL,"title" TEXT NOT NULL,"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE UNIQUE INDEX "DiscoveredResult_monitorId_urlHash_key" ON "DiscoveredResult"("monitorId","urlHash");
CREATE TABLE "TemporalPreference" ("monitorId" UUID PRIMARY KEY,"dateBasis" TEXT NOT NULL DEFAULT 'PUBLISHED',"lookbackDays" INTEGER NOT NULL DEFAULT 7,"since" TIMESTAMP(3),"onlyNew" BOOLEAN NOT NULL DEFAULT TRUE,"notifyUpdates" BOOLEAN NOT NULL DEFAULT TRUE,"requireVerifiedDate" BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT "TemporalPreference_monitorId_fkey" FOREIGN KEY ("monitorId") REFERENCES "Monitor"("id") ON DELETE CASCADE ON UPDATE CASCADE);
